for chapter,pairs in edits.items():
    rel='03-clustering/'+chapter+'.md'
    def op(s):
        for before,after in pairs:
            if before not in s:raise ValueError(before)
            s=s.replace(before,after)
        return s
    transform(rel,op,'Прочитаны исходные единицы текстовой/системной ветки: определены обозначения, отделены вероятности, веса, смысловые классы и поисковые назначения; сохранены ограничения и протокол.',c);save(c)
    parts=sections((ROOT/rel).read_text(encoding='utf8'))
    dest={ident:[title]+extras.get(ident,[]) for title,ids in groups[chapter].items() for ident in ids.split()}
    units=[u for u in c['units'] if u.get('chapter')==chapter and not u.get('provenance_only')]
    assert set(dest)=={u['id'] for u in units}
    for u in units:
        targets=[]
        for j,title in enumerate(dest[u['id']]):
            a,b,body=parts[title];key=u['anchor'] if j==0 else f"t-{chapter}-{u['id']}-{j}"
            c['spans'][key]={'path':rel,'start_line':a,'end_line':b,'sha256':digest(body),'destination_section':title,'status':'revised','review_status':'verified','rationale':'Исходная единица прочитана; сохранены определения, примеры и разные ограничения, исправлено толкование стоимости поиска, добавлены промежуточные шаги.','evidence':'editorial/review-evidence.md#text-systems-clustering'}
            targets.append(key)
        u.update(targets=targets,status='semantic-reviewed',action='объединить с сохранением нюансов')
